-- Owner V2.0, 2026-10-22. Local PostgreSQL/PGlite tested. Hosted Supabase not provisioned.
create schema if not exists spaces_private;
revoke all on schema spaces_private from public;
do $$ begin if not exists(select 1 from pg_roles where rolname='spaces_app') then create role spaces_app nologin; end if; end $$;
create function public.spaces_uid() returns text language sql stable security invoker set search_path=public as $$ select coalesce(nullif(current_setting('request.jwt.claim.sub',true),''),'') $$;
create function public.spaces_org() returns text language sql stable security invoker set search_path=public as $$ select coalesce(current_setting('request.organization_id',true),'') $$;
create table organizations(id text primary key, name text not null check(length(name) between 1 and 120), created_by text not null, created_at timestamptz not null default now());
create table memberships(organization_id text not null references organizations(id), user_id text not null, role text not null check(role in ('admin','editor','viewer','reviewer')), primary key(organization_id,user_id));
create index memberships_user_org on memberships(user_id,organization_id);
alter table memberships enable row level security;
alter table memberships force row level security;
create policy membership_self_read on memberships for select to spaces_app using(user_id=spaces_uid());
create function public.spaces_role(org text) returns text language sql stable security invoker set search_path=public as $$ select role from memberships where organization_id=org and user_id=spaces_uid() $$;
alter table organizations enable row level security;
alter table organizations force row level security;
create policy org_read on organizations for select to spaces_app using(created_by=spaces_uid() or spaces_role(id) is not null);
create policy org_create on organizations for insert to spaces_app with check(created_by=spaces_uid() and spaces_uid()<>'');
create policy org_edit on organizations for update to spaces_app using(spaces_role(id)='admin') with check(spaces_role(id)='admin');
create table spaces_private.users(id text primary key, label text not null);
create table spaces_private.sessions(id text primary key, user_id text not null references spaces_private.users(id), organization_id text not null references organizations(id), expires_at timestamptz not null, revoked boolean not null default false);
create table properties(organization_id text not null references organizations(id), id text not null, title text not null check(length(title) between 1 and 120), description text not null default '', revision integer not null default 1 check(revision>0), archived boolean not null default false, synthetic_only boolean not null check(synthetic_only), created_by text not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table property_revisions(organization_id text not null, property_id text not null, revision integer not null check(revision>0), manifest jsonb not null, created_by text not null, created_at timestamptz not null default now(), primary key(organization_id,property_id,revision), foreign key(organization_id,property_id) references properties(organization_id,id));
create table assets(organization_id text not null, property_id text not null, id text not null, kind text not null check(kind in ('photo','floor-plan','panorama','walkthrough')), status text not null check(status in ('quarantine','clean','rejected')), original_hash text not null, clean_hash text, bytes integer not null check(bytes between 1 and 5242880), width integer, height integer, mime text not null, rights jsonb not null, created_by text not null, created_at timestamptz not null default now(), primary key(organization_id,id), unique(organization_id,property_id,id), foreign key(organization_id,property_id) references properties(organization_id,id));
create table jobs(organization_id text not null, id text not null, property_id text not null, revision integer not null, command jsonb not null, command_hash text not null, idempotency_key text not null, state text not null check(state in ('queued','processing','awaiting-review','approved','rejected','failed','cancelled','unknown-submission')), attempt integer not null default 0 check(attempt between 0 and 3), epoch integer not null default 0, fence text, lease_until timestamptz, output jsonb, error_code text, created_by text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(organization_id,id), unique(organization_id,idempotency_key), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create table outbox(organization_id text not null, id text not null, job_id text not null, delivered boolean not null default false, created_at timestamptz not null default now(), primary key(organization_id,id), foreign key(organization_id,job_id) references jobs(organization_id,id));
create table reviews(organization_id text not null, id text not null, job_id text not null, property_id text not null, revision integer not null, decision text not null check(decision in ('approved','rejected','retake')), reviewer_id text not null, checks jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id), foreign key(organization_id,job_id) references jobs(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create table publications(organization_id text not null, id text not null, property_id text not null, revision integer not null, job_id text not null, review_id text not null, nonce text not null, expires_at timestamptz not null, revoked boolean not null default false, created_at timestamptz not null default now(), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision), foreign key(organization_id,job_id) references jobs(organization_id,id), foreign key(organization_id,review_id) references reviews(organization_id,id));
create table credit_accounts(organization_id text primary key references organizations(id), available bigint not null check(available>=0), reserved bigint not null default 0 check(reserved>=0), currency text not null default 'SIMULATED_MICRO_USD' check(currency='SIMULATED_MICRO_USD'));
create table credit_reservations(organization_id text not null, id text not null, job_id text not null, amount bigint not null check(amount>=0), actual bigint check(actual>=0), status text not null check(status in ('reserved','captured','released')), primary key(organization_id,id), unique(organization_id,job_id), foreign key(organization_id,job_id) references jobs(organization_id,id));
create table cost_ledger(organization_id text not null references organizations(id), id text not null, idempotency_key text not null, kind text not null, amount bigint not null, body jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id), unique(organization_id,idempotency_key));
create table audit_log(organization_id text not null references organizations(id), id text not null, actor_id text not null, action text not null, resource_id text not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table voice_agent_templates(organization_id text not null references organizations(id), id text not null, version integer not null, body jsonb not null, primary key(organization_id,id));
create table property_agent_profiles(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index property_agent_profiles_scope_time on property_agent_profiles(organization_id,property_id,created_at);
create table property_facts(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index property_facts_scope_time on property_facts(organization_id,property_id,created_at);
create table voice_sessions(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index voice_sessions_scope_time on voice_sessions(organization_id,property_id,created_at);
create table voice_tool_calls(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index voice_tool_calls_scope_time on voice_tool_calls(organization_id,property_id,created_at);
create table voice_quality_reviews(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index voice_quality_reviews_scope_time on voice_quality_reviews(organization_id,property_id,created_at);
create table voice_cost_events(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index voice_cost_events_scope_time on voice_cost_events(organization_id,property_id,created_at);
create table analytics_events(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index analytics_events_scope_time on analytics_events(organization_id,property_id,created_at);
create table analytics_consents(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index analytics_consents_scope_time on analytics_consents(organization_id,property_id,created_at);
create table anonymous_sessions(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index anonymous_sessions_scope_time on anonymous_sessions(organization_id,property_id,created_at);
create table property_funnel_rollups(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index property_funnel_rollups_scope_time on property_funnel_rollups(organization_id,property_id,created_at);
create table leads(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index leads_scope_time on leads(organization_id,property_id,created_at);
create table viewing_requests(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index viewing_requests_scope_time on viewing_requests(organization_id,property_id,created_at);
create table campaign_attribution(organization_id text not null, id text not null, property_id text not null, revision integer not null, session_id text not null, body jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '30 days'), primary key(organization_id,id), foreign key(organization_id,property_id,revision) references property_revisions(organization_id,property_id,revision));
create index campaign_attribution_scope_time on campaign_attribution(organization_id,property_id,created_at);
create table partner_workspaces(organization_id text not null references organizations(id), id text not null, body jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table white_label_brands(organization_id text not null references organizations(id), id text not null, body jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table verified_domains(organization_id text not null references organizations(id), id text not null, body jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table branding_assets(organization_id text not null references organizations(id), id text not null, body jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table invitations(organization_id text not null references organizations(id), id text not null, body jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table support_grants(organization_id text not null references organizations(id), id text not null, body jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table retention_requests(organization_id text not null references organizations(id), id text not null, body jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table support_incidents(organization_id text not null references organizations(id), id text not null, body jsonb not null, created_at timestamptz not null default now(), primary key(organization_id,id));
create table partner_assignments(organization_id text not null references organizations(id), child_organization_id text not null unique references organizations(id), aggregate_allowed boolean not null default false, primary key(organization_id,child_organization_id), check(organization_id<>child_organization_id));
create function spaces_private.immutable_record() returns trigger language plpgsql as $$ begin raise exception 'IMMUTABLE_RECORD'; end $$;
create trigger immutable_property_revisions before update or delete on property_revisions for each row execute function spaces_private.immutable_record();
create trigger immutable_reviews before update or delete on reviews for each row execute function spaces_private.immutable_record();
create trigger immutable_cost_ledger before update or delete on cost_ledger for each row execute function spaces_private.immutable_record();
create trigger immutable_audit_log before update or delete on audit_log for each row execute function spaces_private.immutable_record();
create trigger immutable_voice_cost_events before update or delete on voice_cost_events for each row execute function spaces_private.immutable_record();
