create policy retention_requests_read on retention_requests for select to spaces_app using(organization_id=spaces_org() and spaces_role(organization_id) is not null);
create policy retention_requests_insert on retention_requests for insert to spaces_app with check(organization_id=spaces_org() and spaces_role(organization_id) in ('admin','editor'));
create policy retention_requests_update on retention_requests for update to spaces_app using(organization_id=spaces_org() and spaces_role(organization_id) in ('admin','editor')) with check(organization_id=spaces_org() and spaces_role(organization_id) in ('admin','editor'));
alter table support_incidents enable row level security;
alter table support_incidents force row level security;
create policy support_incidents_read on support_incidents for select to spaces_app using(organization_id=spaces_org() and spaces_role(organization_id) is not null);
create policy support_incidents_insert on support_incidents for insert to spaces_app with check(organization_id=spaces_org() and spaces_role(organization_id) in ('admin','editor'));
create policy support_incidents_update on support_incidents for update to spaces_app using(organization_id=spaces_org() and spaces_role(organization_id) in ('admin','editor')) with check(organization_id=spaces_org() and spaces_role(organization_id) in ('admin','editor'));
alter table partner_assignments enable row level security;
alter table partner_assignments force row level security;
create policy partner_assignments_read on partner_assignments for select to spaces_app using(organization_id=spaces_org() and spaces_role(organization_id) in ('admin','editor'));
grant usage on schema public to spaces_app;
grant select,insert,update on public.organizations,public.memberships,public.properties,public.property_revisions,public.assets,public.jobs,public.outbox,public.reviews,public.publications,public.credit_accounts,public.credit_reservations,public.cost_ledger,public.audit_log,public.voice_agent_templates,public.property_agent_profiles,public.property_facts,public.voice_sessions,public.voice_tool_calls,public.voice_quality_reviews,public.voice_cost_events,public.analytics_events,public.analytics_consents,public.anonymous_sessions,public.property_funnel_rollups,public.leads,public.viewing_requests,public.campaign_attribution,public.partner_workspaces,public.white_label_brands,public.verified_domains,public.branding_assets,public.invitations,public.support_grants,public.retention_requests,public.support_incidents,public.partner_assignments to spaces_app;

revoke all on schema spaces_private from spaces_app;
do $$ begin if exists(select 1 from pg_roles where rolname='authenticated') then grant spaces_app to authenticated; end if; end $$;

-- Explicit privileges: do not inherit hosted default anon/authenticated grants.
do $$ declare t record; begin
 for t in select tablename from pg_tables where schemaname='public' and tablename in ('organizations','memberships','properties','property_revisions','assets','jobs','outbox','reviews','publications','credit_accounts','credit_reservations','cost_ledger','audit_log','voice_agent_templates','property_agent_profiles','property_facts','voice_sessions','voice_tool_calls','voice_quality_reviews','voice_cost_events','analytics_events','analytics_consents','anonymous_sessions','property_funnel_rollups','leads','viewing_requests','campaign_attribution','partner_workspaces','white_label_brands','verified_domains','branding_assets','invitations','support_grants','retention_requests','support_incidents','partner_assignments') loop
  execute format('revoke all on public.%I from public',t.tablename);
  if exists(select 1 from pg_roles where rolname='anon') then execute format('revoke all on public.%I from anon',t.tablename); end if;
  if exists(select 1 from pg_roles where rolname='authenticated') then execute format('revoke all on public.%I from authenticated',t.tablename); end if;
 end loop;
end $$;
create policy audit_insert on audit_log for insert to spaces_app with check(organization_id=spaces_org() and actor_id=spaces_uid());

-- Explicit composite session links: an event/voice tool cannot attach to another property revision.
alter table anonymous_sessions add unique(organization_id,property_id,revision,id);
alter table voice_sessions add unique(organization_id,property_id,revision,id);
alter table voice_sessions add foreign key(organization_id,property_id,revision,session_id) references anonymous_sessions(organization_id,property_id,revision,id);
alter table analytics_events add foreign key(organization_id,property_id,revision,session_id) references anonymous_sessions(organization_id,property_id,revision,id);
alter table analytics_consents add foreign key(organization_id,property_id,revision,session_id) references anonymous_sessions(organization_id,property_id,revision,id);
alter table leads add foreign key(organization_id,property_id,revision,session_id) references anonymous_sessions(organization_id,property_id,revision,id);
alter table viewing_requests add foreign key(organization_id,property_id,revision,session_id) references anonymous_sessions(organization_id,property_id,revision,id);
alter table campaign_attribution add foreign key(organization_id,property_id,revision,session_id) references anonymous_sessions(organization_id,property_id,revision,id);
alter table voice_tool_calls add foreign key(organization_id,property_id,revision,session_id) references voice_sessions(organization_id,property_id,revision,id);
alter table voice_quality_reviews add foreign key(organization_id,property_id,revision,session_id) references voice_sessions(organization_id,property_id,revision,id);
alter table voice_cost_events add foreign key(organization_id,property_id,revision,session_id) references voice_sessions(organization_id,property_id,revision,id);
